// Generated by scripts/themes.mjs: edit the themes there, then run `node scripts/themes.mjs`.
// The board's themes, in the chooser's order: id -> display name, page colour (the browser bar), light or dark.
export const THEMES = {
  dark: { name: "Dark", bg: '#060607', light: false },
  light: { name: "Light", bg: '#f1f2f4', light: true },
  dusk: { name: "Dusk", bg: '#1b1530', light: false },
  day: { name: "Day", bg: '#efe4cf', light: true },
  night: { name: "Night", bg: '#080c1a', light: false },
  terminal: { name: "Terminal", bg: '#020a04', light: false },
  contrast: { name: "High Contrast", bg: '#000000', light: false },
  paper: { name: "Paper", bg: '#e9e4d8', light: true },
  synthwave: { name: "Synthwave", bg: '#130824', light: false },
  ocean: { name: "Ocean", bg: '#04161f', light: false },
  sticky: { name: "Sticky Note", bg: '#ffe066', light: true },
  coral: { name: "Coral", bg: '#ffd3c2', light: true },
  candy: { name: "Cotton Candy", bg: '#e4efff', light: true },
  sunset: { name: "Sunset", bg: '#1c0d14', light: false },
  forest: { name: "Forest", bg: '#0e1912', light: false },
} as const;
export type ThemeId = keyof typeof THEMES;
export const THEME_IDS = Object.keys(THEMES) as ThemeId[];
/** What Auto shows: Dark on a dark OS, Light on a light one. */
export const AUTO_THEME = { dark: 'dark', light: 'light' } as const satisfies Record<'dark' | 'light', ThemeId>;
/** A saved board-theme value as a theme id, or null for Auto (anything unknown). */
export const themeOf = (t: string | null | undefined): ThemeId | null => (t && Object.prototype.hasOwnProperty.call(THEMES, t) ? (t as ThemeId) : null);
